// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzz parameters: from address, array of tos (single-element to keep observation simple), and value
    function testFuzz_property(address from, address maybeReceiver, uint256 v) public {
        // Keep tos array of length exactly 1 so we can reason about single call
        vm.assume(maybeReceiver != address(0));
        address[] memory tos = new address[](1);
        tos[0] = maybeReceiver;
        uint[] memory vals = new uint[](1);
        vals[0] = v;

        // Deploy a recorder that implements the exact target function signature
        Recorder rec = new Recorder();

        // Call c.transfer with the recorder's address as caddress. Use try/catch to allow both success and revert
        bool ok;
        try c.transfer(from, address(rec), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any non-empty tos, the reference contract will invoke transferFrom(address,address,uint256)
        // on the callee, so the Recorder's recordedCalls counter should be 1 and the recorded args should match.
        // The mutant with the wrong selector may either not dispatch to that function or be malformed, so
        // the Recorder will not have recorded a matching transferFrom call (recordedCalls == 0) for some inputs.

        // We assert the reference's invariant: if the external call did not revert (ok == true) then the recorder must have
        // exactly one recorded call with the decoded args equal to (from, maybeReceiver, v). This is observed via the recorder's public getters.
        // This assertion holds for the correct contract for all inputs; the mutant will break it for some inputs because the selector is wrong.
        if (ok) {
            // read recorder's public state
            uint256 calls = rec.recordedCalls();
            address r_from = rec.calls_from(0);
            address r_to = rec.calls_to(0);
            uint256 r_val = rec.calls_val(0);

            // single assertion reading contract behaviour
            assertTrue(calls == 1 && r_from == from && r_to == maybeReceiver && r_val == v);
        } else {
            // If the call reverted, the correct contract should not revert under normal circumstances because it uses a valid selector
            // However, some external behaviour could cause revert; to keep the property universal for the correct contract, we allow either
            // success or revert but only assert in the success branch. The mutant will be caught when ok==true but recorder shows mismatch.
            assertTrue(true);
        }
    }
}

// Recorder that implements the exact selector-signature the reference contract computes
contract Recorder {
    // simple arrays to record each call
    address[] public froms;
    address[] public tos;
    uint256[] public vals;

    // function signature must match: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        froms.push(from);
        tos.push(to);
        vals.push(value);
        return true;
    }

    // helpers to read recorded data (automatic getters for arrays are not index-safe in older compilers in this testing style)
    function recordedCalls() external view returns (uint256) {
        return froms.length;
    }
    function calls_from(uint256 i) external view returns (address) {
        return froms[i];
    }
    function calls_to(uint256 i) external view returns (address) {
        return tos[i];
    }
    function calls_val(uint256 i) external view returns (uint256) {
        return vals[i];
    }
}
